*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#0d0b1c;color:var(--ink);font-family:'DM Sans',system-ui,sans-serif}body{min-height:100svh;display:flex;justify-content:center;align-items:center;padding:20px;background:radial-gradient(ellipse at 50% 20%,#252044 0,#121025 44%,#0b0917 100%);overflow-x:hidden}.game-shell{width:min(1100px,100%);position:relative}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 6px 13px}.brand{display:flex;align-items:center;gap:9px;color:#f4efff;text-decoration:none;font-size:12px;letter-spacing:2px;font-weight:600}.brand b{color:#ff81c0;font-weight:800}.brand-mark{font-size:23px;color:#ff69b0}.top-meta,.sound-button{font:10px 'DM Mono',monospace;letter-spacing:1.2px;color:#aaa5c0}.top-meta{display:flex;align-items:center;gap:10px}.top-meta i{width:3px;height:3px;border-radius:50%;background:#716b87}.live-dot{height:6px;width:6px;background:#ff68b1;border-radius:50%;box-shadow:0 0 10px #ff68b1}.sound-button{border:1px solid #39334e;background:#17142b;border-radius:30px;color:#d9d3e8;padding:8px 12px;cursor:pointer}.sound-button span{font-size:9px}.sound-button.off{opacity:.55}.game-frame{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border:1px solid #554364;border-radius:8px;background:#16132a;box-shadow:0 24px 80px #0008,0 0 36px #df59a010;isolation:isolate}.game-frame canvas{display:block;width:100%;height:100%;touch-action:none}.hud{position:absolute;z-index:2;left:4%;right:4%;top:5%;display:grid;grid-template-columns:1fr 86px 1fr;align-items:start;gap:14px;pointer-events:none}.fighter-name{height:24px;display:flex;align-items:center;gap:7px;font:700 13px 'DM Sans',sans-serif;letter-spacing:2px;text-shadow:0 2px 6px #100c24}.fighter-name small{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#c3bdd1;margin-left:4px}.right-hud .fighter-name{justify-content:flex-end}.name-icon{color:#ffd992}.health-track{height:15px;margin-top:3px;background:#1a1529c9;border:1px solid #fff8;border-radius:2px;position:relative;overflow:hidden;transform:skewX(-11deg);box-shadow:0 2px 8px #0007}.health-fill{height:100%;width:100%;transition:width .18s ease;position:absolute;left:0;top:0}.player-health{background:linear-gradient(90deg,#ff4ba6,#ffbd89)}.rival-health{background:linear-gradient(90deg,#8b8bff,#45e7db);left:auto;right:0}.health-shine{position:absolute;inset:1px 0 auto;height:3px;background:#ffffff55}.round-pips{height:13px;display:flex;gap:4px;padding-top:4px}.round-pips i{width:8px;height:8px;border:1px solid #ffbbd9;border-radius:50%;background:#2b203d}.round-pips i.won{background:#ff84bb;box-shadow:0 0 8px #ff69b0}.right-hud .round-pips{justify-content:flex-end}.round-clock{margin-top:0;text-align:center;border:1px solid #fff4;border-radius:4px;background:#120f25b9;box-shadow:0 5px 15px #0003;padding:5px 4px 4px}.round-clock span{display:block;font:7px 'DM Mono',monospace;color:#c9bdd9;letter-spacing:1px}.round-clock strong{display:block;font:13px 'DM Mono',monospace;color:#ffd98b;line-height:16px}.round-clock em{font:700 18px 'DM Mono',monospace;font-style:normal;text-shadow:0 0 12px #fff5}.announce{position:absolute;z-index:3;left:50%;top:41%;transform:translate(-50%,-50%);white-space:nowrap;font:italic 800 clamp(26px,5vw,55px) 'Playfair Display',serif;color:#fff4d9;text-shadow:0 3px 0 #f45aab,0 0 25px #ff59af;opacity:0;pointer-events:none}.announce.show{animation:announce .9s ease both}@keyframes announce{0%{opacity:0;transform:translate(-50%,-20%) scale(.8)}20%,70%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(-50%,-75%) scale(1.05)}}.combo-toast{position:absolute;z-index:3;left:50%;top:25%;transform:translateX(-50%);color:#ffe49e;font:700 12px 'DM Mono',monospace;letter-spacing:2px;text-shadow:0 0 12px #ffbd52;opacity:0;pointer-events:none}.combo-toast.show{animation:toast .75s ease both}@keyframes toast{0%{opacity:0;top:30%}20%,75%{opacity:1;top:25%}100%{opacity:0;top:21%}}.start-screen,.result-screen{position:absolute;z-index:4;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#130e27d9,#100d21b4 56%,#130e27d9);backdrop-filter:blur(2px)}.start-card,.result-card{text-align:center;width:min(440px,86%);padding:24px 20px}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:2.2px;color:#e3c9df}.start-card .eyebrow{display:flex;justify-content:center;align-items:center;gap:10px}.eyebrow span{width:24px;height:1px;background:#ff76b5}.start-card h1{font:700 clamp(38px,7vw,68px)/.91 'Playfair Display',serif;letter-spacing:-2px;margin:17px 0 11px;text-shadow:0 4px 25px #f960af4a}.start-card h1 em{color:#ff9bc6;font-weight:700}.start-card p,.result-card p{color:#d2cadd;font-size:13px;margin:14px 0 22px}.primary-button{background:linear-gradient(115deg,#ff65ad,#ff8d8a);color:#2b1028;border:0;border-radius:3px;font:800 11px 'DM Mono',monospace;letter-spacing:1.5px;padding:14px 22px;cursor:pointer;box-shadow:0 6px 25px #ff5daa45;transition:transform .15s,filter .15s}.primary-button span{font-size:16px;margin-left:12px}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.1)}.start-foot{display:flex;justify-content:space-between;border-top:1px solid #ffffff25;margin-top:26px;padding-top:13px;color:#c1b6cf;font:8px 'DM Mono',monospace;letter-spacing:1px}.start-foot i{color:#ff77b5;font-style:normal}.hidden{display:none!important}.result-card h2{font:italic 800 clamp(30px,6vw,52px) 'Playfair Display',serif;color:#ffc1d9;text-shadow:0 0 28px #ff67b0a0;margin:13px 0 5px}.control-deck{margin-top:13px;min-height:93px;background:linear-gradient(120deg,#17142a,#19162d);border:1px solid #373149;border-radius:6px;display:grid;grid-template-columns:1fr 1px 1fr 1px 1.65fr;align-items:center;padding:9px 16px;gap:14px;box-shadow:0 12px 35px #0003}.deck-divider{width:1px;height:54px;background:#39334d}.deck-label{display:flex;align-items:center;gap:5px;color:#9e97b3;font:8px 'DM Mono',monospace;letter-spacing:1px;margin-bottom:7px}.deck-label>span{margin-right:auto}.deck-label kbd{font:8px 'DM Mono',monospace;border:1px solid #49425e;border-radius:3px;padding:2px 4px;color:#d8d1e8;background:#211d35}.touch-pad,.attack-buttons,.special-buttons{display:flex;gap:6px;align-items:center}.control-button{touch-action:none;user-select:none;-webkit-user-select:none;cursor:pointer;transition:filter .12s,transform .12s,background .12s}.control-button:active,.control-button.pressed{filter:brightness(1.45);transform:scale(.94)}.move-button,.jump-button{height:32px;min-width:36px;border-radius:4px;border:1px solid #45405b;background:#242039;color:#eee9f4;font-size:22px;line-height:20px}.jump-button{margin-left:auto;color:#b8a6e9}.movement-controls{min-width:150px}.deck-label kbd:first-of-type{margin-left:5px}.attack-controls{min-width:162px}.attack-buttons{justify-content:flex-start}.attack-buttons button{width:70px;height:40px;border-radius:4px;display:grid;grid-template-columns:22px 1fr;grid-template-rows:1fr 12px;text-align:left;padding:5px 6px;border:1px solid #63425d;background:linear-gradient(135deg,#402640,#2b2038);color:#ffd7e8}.attack-buttons button span{grid-row:1/3;font-size:19px;align-self:center;color:#ff86bb}.attack-buttons button b,.special b{font:700 8px 'DM Mono',monospace;letter-spacing:.4px;align-self:end}.attack-buttons button small,.special small{font:8px 'DM Mono',monospace;color:#afa3bf;align-self:start}.attack-buttons .kick{border-color:#565078;background:linear-gradient(135deg,#312749,#242039);color:#dcd8ff}.attack-buttons .kick span{color:#ae9cff}.special-controls{min-width:0}.special-buttons{gap:5px}.special{height:40px;flex:1;min-width:0;border:1px solid #47405c;border-radius:4px;background:#211e35;color:#e9e3f2;display:grid;grid-template-columns:18px 1fr;grid-template-rows:1fr 12px;text-align:left;padding:5px}.special span{grid-row:1/3;align-self:center;font-size:15px;color:#ffd883}.special b{font-size:7px;letter-spacing:0;white-space:nowrap}.special small{font-size:7px}.special-two span{color:#82efff}.special-three span{color:#ff81bb}.footer{height:32px;display:flex;align-items:end;justify-content:space-between;color:#78728b;font:8px 'DM Mono',monospace;letter-spacing:1px;padding:0 4px}.footer span:first-child{color:#a79bb5}
@media(max-width:720px){body{padding:10px 8px;align-items:flex-start}.game-shell{margin:auto 0}.topbar{height:39px;padding-bottom:8px}.brand{font-size:10px}.top-meta{font-size:8px;gap:6px}.sound-button{padding:6px 8px}.sound-button span{display:none}.game-frame{border-radius:5px}.hud{left:3%;right:3%;top:4%;grid-template-columns:1fr 54px 1fr;gap:6px}.fighter-name{font-size:10px;letter-spacing:1px;gap:3px}.fighter-name small{font-size:6px;letter-spacing:.4px;margin-left:1px}.health-track{height:11px}.round-clock{padding:3px 2px}.round-clock span{font-size:6px}.round-clock strong{font-size:10px;line-height:12px}.round-clock em{font-size:14px}.control-deck{margin-top:8px;min-height:94px;padding:7px 8px;gap:7px;grid-template-columns:.9fr 1px .95fr 1px 1.6fr}.deck-label{font-size:7px;letter-spacing:.5px;margin-bottom:5px}.deck-label kbd{padding:2px 3px;font-size:7px}.movement-controls{min-width:0}.move-button,.jump-button{height:32px;min-width:30px}.jump-button{margin-left:auto}.attack-controls{min-width:0}.attack-buttons{gap:3px}.attack-buttons button{width:auto;flex:1;height:38px;grid-template-columns:16px 1fr;padding:4px}.attack-buttons button b{font-size:7px}.special-buttons{gap:3px}.special{height:38px;grid-template-columns:13px 1fr;padding:4px}.special span{font-size:13px}.special b{font-size:6px}.special small{font-size:6px}.deck-divider{height:47px}.footer{font-size:6px;letter-spacing:.5px;height:24px}.start-card{padding:12px 8px}.start-card p{font-size:11px;margin:11px 0 16px}.start-foot{margin-top:18px}.primary-button{padding:12px 17px;font-size:9px}}
@media(max-width:420px){body{padding:7px 5px}.top-meta{letter-spacing:.5px}.top-meta i{display:none}.control-deck{padding:6px 5px;gap:5px;grid-template-columns:.78fr 1px .9fr 1px 1.55fr}.deck-label{font-size:6px}.movement-controls .deck-label kbd:nth-of-type(3){display:none}.move-button,.jump-button{min-width:26px}.attack-buttons button b{font-size:6px}.special b{font-size:5.5px}.special{grid-template-columns:11px 1fr;padding:3px}.special span{font-size:12px}.footer span:last-child{display:none}}
@media(orientation:landscape) and (max-height:620px){body{padding:5px}.game-shell{width:min(1000px,calc((100svh - 155px)*1.7778))}.topbar{height:32px;padding-bottom:5px}.control-deck{min-height:78px;margin-top:7px;padding-top:5px;padding-bottom:5px}.footer{height:20px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, FLOOR = 432;
  const ui = {
    start: document.getElementById('startScreen'), result: document.getElementById('resultScreen'),
    startButton: document.getElementById('startButton'), rematch: document.getElementById('rematchButton'),
    resultTitle: document.getElementById('resultTitle'), resultMessage: document.getElementById('resultMessage'),
    announce: document.getElementById('announce'), toast: document.getElementById('comboToast'),
    pHealth: document.getElementById('playerHealth'), rHealth: document.getElementById('rivalHealth'),
    timer: document.getElementById('timer'), round: document.getElementById('roundNumber'),
    pPips: document.getElementById('playerPips'), rPips: document.getElementById('rivalPips'), sound: document.getElementById('soundToggle')
  };
  let game, last = 0, audioCtx = null, soundOn = true;
  const held = new Set(), projectiles = [], particles = [];
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);

  function newFighter(x, facing, player) {
    return { x, y: FLOOR, vx: 0, vy: 0, facing, player, hp: 100, wins: 0, action: 'idle', actionT: 0, hitDone: false, invuln: 0, stun: 0, cooldown: 0, jump: 0, walk: 0, energy: 0, combo: 0, lastHit: 0 };
  }
  function resetMatch() {
    game = { mode: 'fight', p: newFighter(305, 1, true), e: newFighter(655, -1, false), round: 1, timer: 60, modeT: 0, shake: 0, flash: 0, aiT: .8, totalTime: 0 };
    projectiles.length = 0; particles.length = 0; held.clear(); updateHud();
  }
  function startMatch() {
    resetMatch(); ui.start.classList.add('hidden'); ui.result.classList.add('hidden'); announce('FIGHT!'); sound('start');
  }
  function announce(text) { ui.announce.textContent = text; ui.announce.classList.remove('show'); void ui.announce.offsetWidth; ui.announce.classList.add('show'); }
  function toast(text) { ui.toast.textContent = text; ui.toast.classList.remove('show'); void ui.toast.offsetWidth; ui.toast.classList.add('show'); }
  function updateHud() {
    if (!game) return;
    ui.pHealth.style.width = `${Math.max(0, game.p.hp)}%`; ui.rHealth.style.width = `${Math.max(0, game.e.hp)}%`;
    ui.timer.textContent = String(Math.ceil(game.timer)).padStart(2, '0'); ui.round.textContent = String(game.round).padStart(2, '0');
    [...ui.pPips.children].forEach((el, i) => el.classList.toggle('won', i < game.p.wins));
    [...ui.rPips.children].forEach((el, i) => el.classList.toggle('won', i < game.e.wins));
  }

  function startAction(f, type) {
    if (game.mode !== 'fight' || f.stun > 0 || f.action === 'ko') return;
    const special = type.startsWith('special');
    if (f.actionT > 0 && !['idle', 'walk', 'jump', 'guard'].includes(f.action)) return;
    if (special && f.energy < (type === 'special3' ? 45 : 30)) { toast('BUILD YOUR SPIRIT ✦'); return; }
    if (special) f.energy -= type === 'special3' ? 45 : 30;
    f.action = type; f.actionT = type === 'punch' ? .34 : type === 'kick' ? .48 : type === 'special1' ? .62 : type === 'special2' ? .54 : .72; f.hitDone = false;
    if (type === 'special2') { f.vx = f.facing * 470; f.invuln = .34; }
    if (type === 'special3') { game.flash = .16; game.shake = 8; }
    sound(type === 'special1' ? 'magic' : type === 'special3' ? 'magic' : 'swing');
  }
  function actionInput(type) { if (game?.mode === 'fight') startAction(game.p, type); }
  function sound(kind) {
    if (!soundOn) return;
    try {
      audioCtx ||= new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
      const osc = audioCtx.createOscillator(), gain = audioCtx.createGain(), now = audioCtx.currentTime;
      osc.connect(gain); gain.connect(audioCtx.destination);
      const base = kind === 'magic' ? 540 : kind === 'hit' ? 115 : kind === 'start' ? 440 : 220;
      osc.type = kind === 'magic' ? 'sine' : 'triangle'; osc.frequency.setValueAtTime(base, now); osc.frequency.exponentialRampToValueAtTime(base * (kind === 'hit' ? .55 : 1.5), now + .11);
      gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(kind === 'hit' ? .09 : .035, now + .012); gain.gain.exponentialRampToValueAtTime(.0001, now + .16);
      osc.start(now); osc.stop(now + .17);
    } catch (_) { /* Audio is an optional flourish. */ }
  }
  function spawnBurst(x, y, color, count = 12) {
    for (let i = 0; i < count; i++) { const a = Math.random() * Math.PI * 2, speed = rand(40, 260); particles.push({ x, y, vx: Math.cos(a) * speed, vy: Math.sin(a) * speed, life: rand(.25, .65), max: .65, color, size: rand(2, 5), rot: rand(0, 6) }); }
  }
  function hurt(target, damage, source, type) {
    if (target.invuln > 0 || target.action === 'ko') return;
    target.hp = Math.max(0, target.hp - damage); target.stun = type === 'special3' ? .42 : .22; target.action = 'hurt'; target.actionT = target.stun; target.vx = source.facing * (type === 'special3' ? 210 : 120); target.vy = type === 'special3' ? -95 : -20;
    source.energy = Math.min(100, source.energy + 16); source.combo = game.totalTime - source.lastHit < 1.4 ? source.combo + 1 : 1; source.lastHit = game.totalTime;
    game.shake = type === 'special3' ? 12 : 5; spawnBurst(target.x, target.y - 78, type?.startsWith('special') ? '#ffe58c' : '#ff82bf', type === 'special3' ? 26 : 13); sound('hit'); updateHud();
    if (source.combo >= 2) toast(`${source.combo} HIT COMBO!`);
    if (target.hp <= 0) finishRound(source.player ? 'player' : 'rival');
  }
  function finishRound(winner) {
    if (game.mode !== 'fight') return;
    game.mode = 'roundEnd'; game.modeT = 2.2;
    const fighter = winner === 'player' ? game.p : game.e; fighter.wins++;
    announce(winner === 'player' ? (game.p.wins === 2 ? 'PERFECT BLOOM!' : 'AKARI WINS!') : (game.e.wins === 2 ? 'MOONLIGHT WINS!' : 'VESPER WINS!'));
    if (fighter.wins >= 2) {
      game.mode = 'matchEnd'; ui.resultTitle.textContent = winner === 'player' ? 'AKARI WINS!' : 'VESPER WINS!';
      ui.resultMessage.textContent = winner === 'player' ? 'The rooftop belongs to you. Beautifully fought.' : 'The moon has its moment. Ready for a rematch?';
      ui.result.classList.remove('hidden');
    }
  }
  function hitbox(source, target, type) {
    const dx = (target.x - source.x) * source.facing;
    const range = type === 'punch' ? 88 : type === 'kick' ? 112 : type === 'special2' ? 125 : type === 'special3' ? 154 : 0;
    if (dx > 0 && dx < range && Math.abs(target.y - source.y) < (type === 'special3' ? 170 : 115)) {
      hurt(target, type === 'punch' ? 7 : type === 'kick' ? 11 : type === 'special2' ? 19 : 23, source, type); return true;
    }
    return false;
  }
  function launchProjectile(f) {
    projectiles.push({ x: f.x + f.facing * 48, y: f.y - 94, vx: f.facing * 420, life: 1.7, player: f.player, color: f.player ? '#ff80bd' : '#7beaff', spin: 0 });
    spawnBurst(f.x + f.facing * 52, f.y - 94, f.player ? '#ff98ce' : '#8df4ff', 9);
  }

  function updateFighter(f, dt) {
    f.cooldown = Math.max(0, f.cooldown - dt); f.invuln = Math.max(0, f.invuln - dt); f.stun = Math.max(0, f.stun - dt); f.actionT = Math.max(0, f.actionT - dt);
    if (f.actionT <= 0 && ['punch', 'kick', 'special1', 'special2', 'special3', 'hurt', 'guard'].includes(f.action)) f.action = 'idle';
    if (f.player) {
      if (game.mode === 'fight' && f.stun <= 0) {
        let move = (held.has('right') ? 1 : 0) - (held.has('left') ? 1 : 0);
        if (held.has('jump') && f.y >= FLOOR - 1 && f.actionT <= 0) { f.vy = -480; f.action = 'jump'; }
        if (move && f.actionT <= 0) { f.vx = move * 230; f.action = 'walk'; }
        else if (f.action === 'walk') f.action = 'idle';
      }
    }
    f.vy += 1120 * dt; f.y += f.vy * dt;
    if (f.y > FLOOR) { f.y = FLOOR; f.vy = 0; if (f.action === 'jump') f.action = 'idle'; }
    f.x += f.vx * dt; f.vx *= Math.pow(f.stun > 0 || f.action === 'special2' ? .91 : .76, dt * 60);
    f.x = clamp(f.x, 70, 890); f.walk += Math.abs(f.vx) * dt * .018;
  }
  function attackUpdate(f, opponent) {
    const type = f.action;
    if (!['punch', 'kick', 'special1', 'special2', 'special3'].includes(type) || f.hitDone) return;
    const duration = type === 'punch' ? .34 : type === 'kick' ? .48 : type === 'special1' ? .62 : type === 'special2' ? .54 : .72;
    const progress = 1 - f.actionT / duration;
    if (type === 'special1' && progress > .39 && !f.hitDone) { f.hitDone = true; launchProjectile(f); return; }
    const activeAt = type === 'punch' ? .35 : type === 'kick' ? .43 : type === 'special2' ? .34 : type === 'special3' ? .3 : 1;
    if (progress >= activeAt) { f.hitDone = true; if (type !== 'special1') hitbox(f, opponent, type); }
  }
  function cpuUpdate(dt) {
    const e = game.e, p = game.p; if (game.mode !== 'fight' || e.stun > 0) return;
    const distance = Math.abs(p.x - e.x), toward = p.x < e.x ? -1 : 1; e.facing = toward; p.facing = p.x < e.x ? 1 : -1;
    game.aiT -= dt;
    if (e.actionT <= 0) {
      e.vx = distance > 125 ? toward * 105 : distance < 75 ? -toward * 60 : 0;
      e.action = Math.abs(e.vx) > 5 ? 'walk' : 'idle';
      if (game.aiT <= 0) {
        game.aiT = rand(.55, 1.25);
        if (distance < 135) startAction(e, Math.random() < .58 ? 'kick' : 'punch');
        else if (distance < 360 && e.energy >= 30 && Math.random() < .35) startAction(e, 'special1');
        else if (distance < 210 && e.energy >= 45 && Math.random() < .15) startAction(e, 'special3');
        else if (distance < 185 && Math.random() < .2) { e.action = 'guard'; e.actionT = .45; }
      }
    }
  }
  function update(dt) {
    if (!game) return;
    game.totalTime += dt; game.shake = Math.max(0, game.shake - 26 * dt); game.flash = Math.max(0, game.flash - dt);
    if (game.mode === 'fight') {
      game.timer -= dt;
      if (game.timer <= 0) finishRound(game.p.hp >= game.e.hp ? 'player' : 'rival');
      cpuUpdate(dt);
      const dx = game.e.x - game.p.x; const face = dx >= 0 ? 1 : -1;
      if (game.p.actionT <= 0 || game.p.action === 'idle' || game.p.action === 'walk') game.p.facing = face;
      if (game.e.actionT <= 0 || game.e.action === 'idle' || game.e.action === 'walk') game.e.facing = -face;
      updateFighter(game.p, dt); updateFighter(game.e, dt);
      attackUpdate(game.p, game.e); attackUpdate(game.e, game.p);
      if (game.p.x > game.e.x - 42) { const mid = (game.p.x + game.e.x) / 2; game.p.x = mid - 21; game.e.x = mid + 21; }
    } else if (game.mode === 'roundEnd') {
      game.modeT -= dt;
      if (game.modeT <= 0) {
